type OrderStatus = "new" | "preparing" | "ready" | "completed";
type NavKey = "overview" | "admin" | "activities" | "nfc" | "site" | "branches" | "orders" | "pos" | "kds" | "menu" | "tables" | "inventory" | "team" | "marketing" | "storefront" | "reservations" | "remote" | "security" | "health" | "accounts" | "settings" | "languages" | "files" | "stores" | "trend";

type Order = { id: string; table: string; items: string; total: number; status: OrderStatus; time: string; channel: string };
type InstallPromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: "accepted" | "dismissed" }> };

const navItems: { key: NavKey; label: string; icon: typeof LayoutDashboard }[] = [
  { key: "overview", label: "نظرة عامة", icon: LayoutDashboard },
  { key: "admin", label: "Super Admin", icon: ShieldCheck },
  { key: "branches", label: "الفروع والإعدادات", icon: Store },
  { key: "orders", label: "الطلبات", icon: ShoppingBag },
  { key: "pos", label: "نقطة البيع POS", icon: WalletCards },
  { key: "kds", label: "شاشة المطبخ KDS", icon: ChefHat },
  { key: "menu", label: "المنيو والأصناف", icon: Utensils },
  { key: "tables", label: "الطاولات", icon: Table2 },
  { key: "inventory", label: "المخزون والمشتريات", icon: Boxes },
  { key: "team", label: "الموظفون والحضور", icon: Users },
  { key: "marketing", label: "التسويق والحملات", icon: Megaphone },
  { key: "storefront", label: "المتجر", icon: Store },
  { key: "reservations", label: "الحجوزات والانتظار", icon: Clock3 },
  { key: "remote", label: "التوظيف عن بُعد", icon: Users },
  { key: "security", label: "أمان الحساب والجلسات", icon: ShieldCheck },
  { key: "health", label: "صحة النظام", icon: Activity },
];

const statusLabels: Record<OrderStatus, string> = { new: "جديد", preparing: "قيد التحضير", ready: "جاهز", completed: "مكتمل" };
const statusStyles: Record<OrderStatus, string> = { new: "bg-amber-50 text-amber-700 border-amber-200", preparing: "bg-blue-50 text-blue-700 border-blue-200", ready: "bg-emerald-50 text-emerald-700 border-emerald-200", completed: "bg-slate-100 text-slate-600 border-slate-200" };

function money(value: number) { return `${value.toLocaleString("ar-SA")} ر.س`; }

export default function Home() {
  const { user, loading, logout } = useAuth();
  const [testEmail, setTestEmail] = useState("nfood@ret.com");
  const [testPassword, setTestPassword] = useState("");
  const testLogin = trpc.auth.testLogin.useMutation({ onSuccess: () => { toast.success("تم تسجيل الدخول لحساب الاختبار"); window.location.reload(); }, onError: (error) => toast.error(error.message || "بيانات الدخول غير صحيحة") });
  const [active, setActive] = useState<NavKey>("overview");
  const visibleNavItems = useMemo(() => { if (user?.role === "admin" || user?.testRole === "admin") return []; const role = user?.testRole; if (!role) return navItems; const keys = roleNavigation[role as keyof typeof roleNavigation] ?? ["overview"]; return navItems.filter((item) => (keys as readonly string[]).includes(item.key)); }, [user?.role, user?.testRole]);
  const [selectedRestaurantId, setSelectedRestaurantId] = useState(1);
  const restaurantsQuery = trpc.platform.restaurants.useQuery(undefined, { enabled: Boolean(user), retry: false });
  useEffect(() => { const restaurants = restaurantsQuery.data ?? []; if (!restaurants.length) return; const available = restaurants.some((restaurant) => restaurant.id === selectedRestaurantId); if (!available) setSelectedRestaurantId(restaurants[0].id); }, [restaurantsQuery.data, selectedRestaurantId]);
  const workspaceState = getWorkspaceState(restaurantsQuery.data ?? [], selectedRestaurantId);
  const isCentralAdmin = user?.role === "admin" || user?.testRole === "admin";
  const adminPanelChildren = useMemo(() => {
    switch (active as CentralAdminNavKey) {
      case "admin": return <SuperAdminView />;
      case "activities": return <ActivitiesSectorsAdmin />;
      case "accounts": return <AccountManagementPanel />;
      case "settings": return <PlatformSettingsPanel initialSection="advanced" />;
      case "site": return <PlatformSettingsPanel initialSection="site" />;
      case "languages": return <UiTranslationAdminPanel />;
      case "files": return <MediaLibraryPanel isCentralAdmin />;
      case "stores": return <MarketplaceStoresView />;
      case "trend": return <ContentMarketplace />;
      case "nfc": return <VcardCardsAdmin />;
      case "security": return <SecurityView />;
      case "health": return <SystemHealthView />;
      case "overview": return undefined;
    }
  }, [active]);
  const adminPanelProps = isCentralAdmin ? { children: adminPanelChildren } : {};
  const utils = trpc.useUtils();
  const workspaceReady = Boolean(user && workspaceState === "ready");
  useEffect(() => { if (isCentralAdmin) setActive("admin"); }, [isCentralAdmin]);
  const [profileOpen, setProfileOpen] = useState(false);
  const [profileImageUploading, setProfileImageUploading] = useState(false);
  const profileImageUpload = trpc.uploadBrandAsset.useMutation({ onSuccess: async () => { await utils.platform.branding.invalidate({ restaurantId: selectedRestaurantId }); toast.success("تم تحديث أيقونة المطعم"); }, onError: (error) => toast.error(error.message || "تعذر تحديث أيقونة المطعم") });
  const uploadRestaurantProfileImage = (file: File | undefined) => { if (!file) return; if (!["image/png", "image/jpeg", "image/webp"].includes(file.type)) { toast.error("يسمح برفع PNG أو JPG أو WEBP فقط"); return; } if (file.size > 5 * 1024 * 1024) { toast.error("الحد الأقصى للصورة 5MB"); return; } setProfileImageUploading(true); const reader = new FileReader(); reader.onload = async () => { const data = String(reader.result || "").split(",")[1]; if (!data) { setProfileImageUploading(false); toast.error("تعذر قراءة الصورة"); return; } try { await profileImageUpload.mutateAsync({ restaurantId: selectedRestaurantId, assetType: "pwaIcon", data, mimeType: file.type as "image/png" | "image/jpeg" | "image/webp", fileName: file.name }); } finally { setProfileImageUploading(false); } }; reader.onerror = () => { setProfileImageUploading(false); toast.error("تعذر قراءة الصورة"); }; reader.readAsDataURL(file); };
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [commandQuery, setCommandQuery] = useState("");
  const globalSearchQuery = trpc.platform.globalSearch.useQuery({ restaurantId: selectedRestaurantId, query: commandQuery, limit: 20 }, { enabled: commandOpen && commandQuery.trim().length >= 2 && workspaceReady, retry: false });
  const roleSummaryQuery = trpc.platform.roleSummary.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: false });
  const workspaceBranches = trpc.platform.branches.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: false });
  const brandingQuery = trpc.platform.branding.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: false });
  const [globalForbiddenAction, setGlobalForbiddenAction] = useState<string | null>(null);
  useEffect(() => { if (globalSearchQuery.error?.data?.code === "FORBIDDEN") setGlobalForbiddenAction("global.search"); else if (roleSummaryQuery.error?.data?.code === "FORBIDDEN") setGlobalForbiddenAction("dashboard.summary"); }, [globalSearchQuery.error, roleSummaryQuery.error]);
  useEffect(() => { const onForbidden = (event: Event) => { const action = (event as CustomEvent<{ action?: string }>).detail?.action; setGlobalForbiddenAction(action || "protected.action"); }; window.addEventListener("nfood:forbidden", onForbidden); return () => window.removeEventListener("nfood:forbidden", onForbidden); }, []);
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);
  const [pwaInstalled, setPwaInstalled] = useState(() => typeof window !== "undefined" && window.matchMedia?.("(display-mode: standalone)").matches);
  const [pushStatus, setPushStatus] = useState<NotificationPermission | "unsupported">(() => typeof Notification === "undefined" ? "unsupported" : Notification.permission);
  const pushSubscribe = trpc.notifications.pushSubscribe.useMutation();
  const enablePush = async () => { if (typeof Notification === "undefined" || !("serviceWorker" in navigator)) { toast.error("المتصفح الحالي لا يدعم إشعارات Push"); return; } const permission = await Notification.requestPermission(); setPushStatus(permission); if (permission !== "granted") { toast.info("لم يتم تفعيل الإشعارات"); return; } try { const registration = await navigator.serviceWorker.ready; const subscription = await registration.pushManager.getSubscription(); if (subscription) { const json = subscription.toJSON(); if (json.endpoint && json.keys?.p256dh && json.keys.auth) { await pushSubscribe.mutateAsync({ endpoint: json.endpoint, keys: { p256dh: json.keys.p256dh, auth: json.keys.auth }, userAgent: navigator.userAgent }); toast.success("تم تفعيل إشعارات NFOOD وحفظ الجهاز"); return; } } toast.info("تم السماح بالإشعارات. يلزم ربط مفتاح Push للإرسال الإنتاجي."); } catch { toast.error("تعذر حفظ اشتراك الإشعارات"); } };
  useEffect(() => { const capture = (event: Event) => { event.preventDefault(); setInstallPrompt(event as InstallPromptEvent); }; const installed = () => { setPwaInstalled(true); setInstallPrompt(null); toast.success("تم تثبيت تطبيق NFOOD"); }; window.addEventListener("beforeinstallprompt", capture); window.addEventListener("appinstalled", installed); return () => { window.removeEventListener("beforeinstallprompt", capture); window.removeEventListener("appinstalled", installed); }; }, []);
  useEffect(() => {
    const manifestLink = document.querySelector<HTMLLinkElement>('link[rel="manifest"]');
    const themeMeta = document.querySelector<HTMLMetaElement>('meta[name="theme-color"]');
    if (!manifestLink) return;
    const defaultTitle = "NFOOD Restaurant SaaS";
    if (!user) {
      document.title = defaultTitle;
      if (themeMeta) themeMeta.content = "#e76f3c";
      manifestLink.href = "/manifest.webmanifest";
      return;
    }
    const role = user.testRole ?? (user.role === "admin" ? "restaurant_admin" : "customer");
    const brand = brandingQuery.data;
    document.title = brand?.brandName || defaultTitle;
    if (themeMeta) themeMeta.content = brand?.brandColor || "#e76f3c";
    let objectUrl: string | null = null;
    if (brand?.brandName) {
      const icon = brand.brandLogoUrl || "/icon-maskable.svg";
      const manifest = { name: brand.brandName, short_name: brand.brandName.slice(0, 32), lang: "ar", dir: "rtl", start_url: "/", display: "standalone", theme_color: brand.brandColor || "#e76f3c", background_color: "#f6f7f9", description: brand.brandDescription || `تطبيق ${brand.brandName}`, icons: [{ src: icon, sizes: "512x512", type: "image/png", purpose: "any maskable" }] };
      objectUrl = URL.createObjectURL(new Blob([JSON.stringify(manifest)], { type: "application/manifest+json" }));
      manifestLink.href = objectUrl;
    } else {
      manifestLink.href = `/manifest.${role}.webmanifest`;
    }
    return () => {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      manifestLink.href = "/manifest.webmanifest";
      document.title = defaultTitle;
      if (themeMeta) themeMeta.content = "#e76f3c";
    };
  }, [brandingQuery.data, user?.role, user?.testRole, Boolean(workspaceReady)]);
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") setCommandOpen(false); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, []);
  const notificationsQuery = trpc.notifications.mine.useQuery(undefined, { enabled: Boolean(user), retry: false, refetchInterval: 5000 });
  const markNotificationRead = trpc.notifications.markRead.useMutation({ onSuccess: () => notificationsQuery.refetch() });
  const remoteOrders = trpc.platform.ordersByRestaurant.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: false, refetchInterval: 5000 });
  const updateOrderStatus = trpc.platform.updateOrderStatus.useMutation({ onSuccess: () => { remoteOrders.refetch(); toast.success("تم حفظ حالة الطلب في قاعدة البيانات"); }, onError: (error) => toast.error(`تعذر تحديث الطلب: ${error.message}`) });
  const [branch, setBranch] = useState("");
  useEffect(() => { const firstBranch = workspaceBranches.data?.[0]; setBranch((current) => current && workspaceBranches.data?.some((item) => item.name === current) ? current : firstBranch?.name ?? ""); }, [workspaceBranches.data]);
  const [query, setQuery] = useState("");
  const orders = useMemo(() => (remoteOrders.data ?? []).map((order) => ({ id: `#${order.id}`, table: order.tableName ?? "بدون طاولة", items: "بنود محفوظة في الطلب", total: Number(order.total), status: order.status === "cancelled" ? "completed" : order.status, time: new Date(order.createdAt).toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" }), channel: order.channel === "dine_in" ? "داخل المطعم" : order.channel === "takeaway" ? "استلام" : "توصيل", ageMinutes: 0 })), [remoteOrders.data]);
  const visibleOrders = useMemo(() => orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(query)), [orders, query]);
  const advanceOrder = (id: string) => {
    const current = orders.find((order) => order.id === id);
    if (!current) return;
    const next: OrderStatus = current.status === "new" ? "preparing" : current.status === "preparing" ? "ready" : "completed";
    const numericId = Number(id.replace("#", ""));
    if (!remoteOrders.data?.some((order) => order.id === numericId)) { toast.error("الطلب غير موجود في بيانات backend الحالية"); return; }
    updateOrderStatus.mutate({ restaurantId: selectedRestaurantId, orderId: numericId, status: next });
  };

  const handleLogout = async () => { await executeLogoutFlow({ logout, closeMenu: () => setProfileOpen(false), redirect: () => { window.location.href = "/"; }, notifySuccess: () => toast.success("تم تسجيل الخروج"), notifyError: (message) => toast.error(message) }); };
  const handleSwitchAccount = async () => { await executeSwitchAccountFlow({ logout, closeMenu: () => setProfileOpen(false), startLogin, redirect: () => undefined, notifyError: (message) => toast.error(message) }); };

  if (loading) return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f7f9] text-slate-500">جارٍ التحقق من الجلسة...</div>;
    if (!user) return <TestLoginScreen email={testEmail} password={testPassword} setEmail={setTestEmail} setPassword={setTestPassword} onSubmit={() => testLogin.mutate({ email: testEmail, password: testPassword })} pending={testLogin.isPending} onOAuth={() => startLogin()} />;
  if (restaurantsQuery.isError && !isCentralAdmin) return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f7f9] p-6"><Card className="w-full max-w-lg rounded-3xl border-red-200 bg-white shadow-sm"><CardContent className="p-8 text-center"><Store className="mx-auto mb-4 h-12 w-12 text-red-500" /><h1 className="text-2xl font-bold text-slate-900">تعذر تحميل مساحة العمل</h1><p className="mt-3 text-sm leading-7 text-slate-500">تعذر الوصول إلى بيانات المطاعم الآن. Request ID: restaurants-workspace</p><div className="mt-6 flex flex-wrap items-center justify-center gap-3"><Button type="button" onClick={() => void restaurantsQuery.refetch()} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">إعادة المحاولة</Button><Button type="button" variant="outline" onClick={() => void handleLogout()} className="rounded-xl border-slate-200 text-slate-700">خروج</Button></div></CardContent></Card></div>;
  if (restaurantsQuery.isSuccess && workspaceState === "empty" && !isCentralAdmin) return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f7f9] p-6"><Card className="w-full max-w-lg rounded-3xl border-slate-200 bg-white shadow-sm"><CardContent className="p-8 text-center"><Store className="mx-auto mb-4 h-12 w-12 text-[#e76f3c]" /><h1 className="text-2xl font-bold text-slate-900">لا توجد مساحة عمل مرتبطة</h1><p className="mt-3 text-sm leading-7 text-slate-500">حسابك مسجل بنجاح، لكن لا يوجد مطعم مرتبط به حتى الآن. اطلب من مسؤول المنصة إنشاء المطعم أو ربط حسابك به، ثم أعد المحاولة.</p><div className="mt-6 flex flex-wrap items-center justify-center gap-3"><Button type="button" onClick={() => void restaurantsQuery.refetch()} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">إعادة المحاولة</Button><Button type="button" variant="outline" onClick={() => void handleLogout()} className="rounded-xl border-slate-200 text-slate-700">خروج</Button></div></CardContent></Card></div>;
  if (isCentralAdmin) return <CentralAdminCommandCenter active={active as CentralAdminNavKey} onNavigate={(key) => setActive(key as NavKey)} orders={orders} userName={user?.name ?? undefined} userEmail={user?.email ?? undefined} onLogout={() => void handleLogout()} {...adminPanelProps} />;
  const title = navItems.find((item) => item.key === active)?.label ?? "نظرة عامة";
  const todayLabel = new Date().toLocaleDateString("ar-SA", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  const roleDashboardTitle = isCentralAdmin ? "لوحة Super Admin · إدارة المنصة" : ({ restaurant_admin: "صباح الخير، فريق NFOOD", waiter: "لوحة النادل · جاهز لخدمة الضيوف", kitchen: "لوحة المطبخ · الطلبات بانتظار التنفيذ", cashier: "لوحة الكاشير · راقب المدفوعات والطلبات", customer: "مرحباً بك في NFOOD", driver: "لوحة التوصيل · تابع مهامك الحالية" } as Record<string, string>)[user?.testRole ?? "restaurant_admin"] ?? "صباح الخير، فريق NFOOD";
  return (
    <div dir="rtl" className="min-h-screen bg-[#f6f7f9] text-[#182230]">
      <aside className="fixed inset-y-0 right-0 z-20 hidden w-[272px] border-l border-slate-200 bg-[#111c2e] text-white lg:flex lg:flex-col">
        <div className="flex h-20 items-center gap-3 border-b border-white/10 px-7">
          <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#e76f3c] shadow-lg shadow-orange-900/20"><Utensils className="h-5 w-5" /></div>
          <div><div className="text-[17px] font-bold tracking-tight">NFOOD</div><div className="text-[10px] font-medium text-slate-400">RESTAURANT OPERATING SYSTEM</div></div>
        </div>
        <div className="px-5 pt-7"><p className="mb-3 px-3 text-[10px] font-bold tracking-[.18em] text-slate-500">مساحة العمل</p>
          <nav className="space-y-1">{visibleNavItems.map((item) => { const Icon = item.icon; const isActive = item.key === active; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-[13px] transition-all ${isActive ? "bg-[#e76f3c] font-semibold text-white shadow-lg shadow-orange-950/20" : "text-slate-400 hover:bg-white/5 hover:text-white"}`}><Icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{item.key === "orders" && <span className="mr-auto rounded-full bg-white/15 px-2 py-0.5 text-[10px] text-white">{remoteOrders.isLoading ? "…" : remoteOrders.data?.length ?? 0}</span>}</button>; })}</nav>
        </div>
        <div className="mt-auto space-y-4 p-5"><div className="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><Zap className="h-4 w-4 text-[#f0ad65]" /> الاشتراك</div><p className="text-sm font-bold">إدارة الباقة</p><p className="mt-1 text-[11px] leading-5 text-slate-400">تظهر تفاصيل الباقة والفترة من بيانات الاشتراك المحفوظة في لوحة الإدارة.</p></div>{pushStatus === "default" && <button onClick={enablePush} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white"><Bell className="h-4 w-4" /> تفعيل إشعارات NFOOD</button>}{pushStatus === "granted" && <p className="px-3 py-2 text-xs text-emerald-400">إشعارات NFOOD مفعّلة</p>}{pwaInstalled ? <p className="px-3 py-2 text-xs text-emerald-400">تطبيق NFOOD مثبت على هذا الجهاز</p> : installPrompt ? <button onClick={async () => { await installPrompt.prompt(); const result = await installPrompt.userChoice; if (result.outcome === "accepted") toast.success("تم بدء تثبيت تطبيق NFOOD"); setInstallPrompt(null); }} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-[#f0ad65] hover:text-white"><Zap className="h-4 w-4" /> تثبيت تطبيق NFOOD</button> : <p className="px-3 py-2 text-xs text-slate-500">التثبيت متاح من قائمة المتصفح عند استيفاء الشروط</p>}<button onClick={() => { window.location.href = "/marketplace"; }} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-[#f0ad65] hover:text-white"><Store className="h-4 w-4" /> سوق NFOOD</button><button onClick={() => setActive("branches")} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white"><Settings2 className="h-4 w-4" /> الإعدادات العامة</button></div>
      </aside>
      <main className="lg:mr-[272px]">
        <header className="sticky top-0 z-10 flex h-20 items-center justify-between border-b border-slate-200/80 bg-[#f6f7f9]/90 px-5 backdrop-blur-xl md:px-8"><div><div className="mb-1 flex items-center gap-2 text-xs text-slate-500"><span>مساحة العمل</span><span>/</span><span className="font-medium text-slate-700">{restaurantsQuery.isLoading ? "جارٍ تحميل المطعم..." : restaurantsQuery.data?.find((restaurant) => restaurant.id === selectedRestaurantId)?.name ?? "لا يوجد مطعم مرتبط"}</span></div><h1 className="text-xl font-bold tracking-tight md:text-2xl">{title}</h1></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold shadow-sm sm:flex"><Store className="h-4 w-4 text-[#e76f3c]" />{(restaurantsQuery.data?.length ?? 0) > 1 ? <select aria-label="اختيار المطعم" value={selectedRestaurantId} onChange={(e) => setSelectedRestaurantId(Number(e.target.value))} className="max-w-40 bg-transparent outline-none">{(restaurantsQuery.data ?? []).map((restaurant, index) => <option key={restaurant.id} value={restaurant.id}>{restaurant.name}{index === 0 ? " · الرئيسي" : ""}</option>)}</select> : <span className="max-w-40 truncate">{restaurantsQuery.isLoading ? "جارٍ تحميل المطعم..." : restaurantsQuery.data?.[0]?.name ?? "لا يوجد مطعم"}</span>}{(workspaceBranches.data?.length ?? 0) > 0 && <><span className="text-slate-300">/</span><select aria-label="اختيار الفرع" value={branch} onChange={(e) => setBranch(e.target.value)} className="bg-transparent outline-none"><option value="">الفرع الرئيسي</option>{(workspaceBranches.data ?? []).map((item) => <option key={item.id} value={item.name}>{item.name}</option>)}</select></>}</div>{brandingQuery.data?.slug && <button type="button" onClick={() => window.open(`/menu/${encodeURIComponent(brandingQuery.data!.slug)}?preview=1`, "_blank", "noopener,noreferrer")} className="hidden items-center gap-2 rounded-xl border border-orange-200 bg-orange-50 px-3 py-2 text-xs font-bold text-[#e76f3c] shadow-sm hover:bg-orange-100 md:flex"><Eye className="h-4 w-4" /> دخول المنيو</button>}<button aria-label="فتح البحث العام" onClick={() => setCommandOpen(true)} className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs text-slate-500 shadow-sm hover:text-[#e76f3c] sm:flex"><Search className="h-4 w-4" /> بحث شامل <kbd className="rounded bg-slate-100 px-1.5 py-0.5 text-[10px]">Ctrl K</kbd></button><div className="relative"><button aria-label="فتح الإشعارات" aria-expanded={notificationOpen} onClick={() => setNotificationOpen((open) => !open)} className="relative rounded-xl border border-slate-200 bg-white p-2.5 text-slate-500 shadow-sm hover:text-[#e76f3c]"><Bell className="h-[18px] w-[18px]" />{(notificationsQuery.data ?? []).some((item) => !item.readAt) && <span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#e76f3c]" />}</button>{notificationOpen && <div className="absolute left-0 top-12 z-50 w-80 rounded-2xl border border-slate-200 bg-white p-2 shadow-xl"><div className="flex items-center justify-between border-b border-slate-100 px-3 py-2"><p className="text-sm font-bold">الإشعارات</p><span className="text-[10px] text-slate-400">{notificationsQuery.data?.length ?? 0}</span></div><div className="max-h-72 overflow-y-auto">{(notificationsQuery.data ?? []).length === 0 ? <p className="px-3 py-8 text-center text-xs text-slate-500">لا توجد إشعارات.</p> : (notificationsQuery.data ?? []).map((item) => <button key={item.id} onClick={() => markNotificationRead.mutate({ notificationId: item.id })} className={`w-full rounded-xl px-3 py-3 text-right hover:bg-orange-50 ${item.readAt ? "opacity-60" : ""}`}><p className="text-xs font-bold">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.body}</p></button>)}</div></div>}</div><div className="relative hidden sm:block"><button aria-label="فتح قائمة ملف المطعم" aria-expanded={profileOpen} onClick={() => setProfileOpen((open) => !open)} className="flex h-9 w-9 items-center justify-center overflow-hidden rounded-xl bg-[#e76f3c] text-sm font-bold text-white shadow-sm transition hover:bg-[#d85f2e]">{brandingQuery.data?.pwaInstallIconUrl ? <img src={brandingQuery.data.pwaInstallIconUrl} alt="" className="h-full w-full object-cover" /> : user?.name?.[0] || "م"}</button>{profileOpen && <div className="absolute left-0 top-11 z-50 w-64 rounded-2xl border border-slate-200 bg-white p-2 text-right shadow-xl"><div className="border-b border-slate-100 px-3 py-3"><p className="text-sm font-bold">{user?.name || "حساب NFOOD"}</p><p className="mt-1 truncate text-xs text-slate-500">{user?.email || "لم يتم تسجيل الدخول"}</p></div><label className="mt-2 flex w-full cursor-pointer items-center rounded-xl px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-[#e76f3c]"><input type="file" accept="image/png,image/jpeg,image/webp" className="hidden" disabled={profileImageUploading} onChange={(event) => { uploadRestaurantProfileImage(event.target.files?.[0]); event.currentTarget.value = ""; }} />{profileImageUploading ? "جارٍ رفع أيقونة المطعم..." : "تغيير أيقونة المطعم"}</label>{brandingQuery.data?.slug && <button onClick={() => window.open(`/menu/${encodeURIComponent(brandingQuery.data!.slug)}?preview=1`, "_blank", "noopener,noreferrer")} className="flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-[#e76f3c]">معاينة المنيو العام</button>}<button onClick={handleSwitchAccount} className="flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-[#e76f3c]">تبديل الحساب</button><button onClick={handleLogout} className="flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-red-600 hover:bg-red-50">تسجيل الخروج</button></div>}</div></div></header>{commandOpen && <div className="fixed inset-0 z-[80] flex items-start justify-center bg-slate-950/30 px-4 pt-24" onMouseDown={() => setCommandOpen(false)}><div className="w-full max-w-2xl overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl" onMouseDown={(event) => event.stopPropagation()}><div className="flex items-center gap-3 border-b border-slate-100 px-4 py-3"><Search className="h-5 w-5 text-slate-400" /><input autoFocus value={commandQuery} onChange={(event) => setCommandQuery(event.target.value)} placeholder="ابحث في الوحدات والطلبات..." className="flex-1 bg-transparent text-sm outline-none" /><kbd className="rounded bg-slate-100 px-2 py-1 text-[10px] text-slate-500">Esc</kbd></div><div className="max-h-[55vh] overflow-y-auto p-2">{globalSearchQuery.isLoading && <p className="px-3 py-3 text-xs text-slate-500">جارٍ البحث داخل بيانات المطعم...</p>}{globalSearchQuery.isError && <p className="px-3 py-3 text-xs text-red-600">تعذر البحث الآن. Request ID: search-{selectedRestaurantId}</p>}{globalSearchQuery.data?.results.map((result) => <button key={`${result.type}-${result.id}`} onClick={() => { setActive(result.action as NavKey); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-orange-50"><Search className="h-4 w-4 text-[#e76f3c]" /><span className="text-sm font-semibold">{result.title}</span><span className="mr-auto text-xs text-slate-400">{result.subtitle}</span></button>)}{navItems.filter((item) => visibleNavItems.some((visible) => visible.key === item.key) && item.label.includes(commandQuery)).map((item) => { const Icon = item.icon; return <button key={item.key} onClick={() => { setActive(item.key); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-orange-50"><Icon className="h-4 w-4 text-[#e76f3c]" /><span className="text-sm font-semibold">{item.label}</span><span className="mr-auto text-xs text-slate-400">وحدة</span></button>; })}{orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(commandQuery)).slice(0, 5).map((order) => <button key={order.id} onClick={() => { setActive("orders"); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-slate-50"><ShoppingBag className="h-4 w-4 text-slate-400" /><span className="text-sm font-semibold">{order.id} · {order.table}</span><span className="mr-auto text-xs text-slate-400">طلب</span></button>)}{navItems.filter((item) => visibleNavItems.some((visible) => visible.key === item.key) && item.label.includes(commandQuery)).length === 0 && orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(commandQuery)).length === 0 && (globalSearchQuery.data?.results.length ?? 0) === 0 && !globalSearchQuery.isLoading && <p className="px-3 py-10 text-center text-sm text-slate-500">لا توجد نتائج مطابقة.</p>}</div></div></div>}\n        <div className="border-b border-slate-200 bg-white px-4 py-2 lg:hidden"><div className="flex gap-2 overflow-x-auto pb-1">{visibleNavItems.map((item) => { const Icon = item.icon; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-2 text-[11px] font-semibold ${active === item.key ? "bg-orange-50 text-[#e76f3c]" : "text-slate-500"}`}><Icon className="h-3.5 w-3.5" />{item.label}</button>; })}</div></div><div className="p-4 pb-24 md:p-8 lg:pb-8">{active === "overview" && <div className="mb-7 flex items-end justify-between"><div><p className="text-sm text-slate-500">{todayLabel}</p><h2 className="mt-1 text-2xl font-bold">{roleDashboardTitle}</h2></div>{(isCentralAdmin || isRoleActionAllowed(user?.testRole, "orders.create")) && <Button onClick={() => { setActive("pos"); toast.success("تم فتح نقطة البيع"); }} className="hidden gap-2 rounded-xl bg-[#e76f3c] px-4 shadow-lg shadow-orange-200 hover:bg-[#d85f2e] sm:flex"><Plus className="h-4 w-4" /> طلب جديد</Button>}</div>}
          {globalForbiddenAction ? <AccessDeniedView feature={globalForbiddenAction} /> : active === "overview" && user?.testRole === "restaurant_admin" ? <RestaurantCommandCenter orders={visibleOrders} advanceOrder={advanceOrder} summary={roleSummaryQuery.data} summaryLoading={roleSummaryQuery.isLoading} onNavigate={(key) => setActive(key)} /> : active === "overview" ? <Overview orders={visibleOrders} advanceOrder={advanceOrder} query={query} setQuery={setQuery} role={user?.testRole} onNavigate={setActive} summary={roleSummaryQuery.data} summaryLoading={roleSummaryQuery.isLoading} summaryError={roleSummaryQuery.isError} /> : !visibleNavItems.some((item) => item.key === active) ? <AccessDeniedView feature={active} /> : <ModuleView active={active} orders={visibleOrders} advanceOrder={advanceOrder} setActive={setActive} restaurantId={selectedRestaurantId} ordersLoading={remoteOrders.isLoading} ordersError={remoteOrders.isError} />}
        </div>
        <nav className="fixed inset-x-0 bottom-0 z-40 flex border-t border-slate-200 bg-white/95 p-2 shadow-[0_-8px_24px_rgba(15,27,45,.08)] backdrop-blur lg:hidden">{visibleNavItems.slice(0, 4).map((item) => { const Icon = item.icon; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex flex-1 flex-col items-center gap-1 rounded-xl py-2 text-[10px] font-semibold ${active === item.key ? "bg-orange-50 text-[#e76f3c]" : "text-slate-500"}`}><Icon className="h-4 w-4" />{item.label}</button>; })}</nav>
      </main>
    </div>
  );
}

